import java.util.*;import com.koios.client.arpg.PanelCards;import com.koios.game.arpg.*;import com.koios.game.model.player.Player;import com.koios.game.model.item.Item;import com.koios.network.GamePacket;
public final class PanelCardsCheck {
 static int checks;static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
 static String payload(Player p,String tab){((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.clear();PrototypePanel.show(p,tab);for(GamePacket packet:((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets)if(packet.getOpcode()==126){String text=packet.readString();if((packet.readShortA()&65535)==65531)return text;}throw new AssertionError("No panel packet");}
 static String[] lines(String payload){return new String(Base64.getDecoder().decode(payload),java.nio.charset.StandardCharsets.UTF_8).split("\n");}
 static void rectangle(PanelCards cards,int x,int y,int w,int h,String action){for(int[] at:new int[][]{{x,y},{x+w-1,y},{x,y+h-1},{x+w-1,y+h-1},{x+w/2,y+h/2}})check(action.equals(cards.actionAt(at[0],at[1])),"Card boundary targets "+action);check(!action.equals(cards.actionAt(x+w,y+h/2))&&!action.equals(cards.actionAt(x+w/2,y+h)),"Card excludes far boundary "+action);}
 public static void main(String[]args)throws Exception{
  PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("cardaudit",49);p.allowSaveRequests=false;p.setAttribute("tutorial-stage",11);for(int i=0;i<8;i++)p.getInventory().set(i,MapRuns.map(i%3+1,new int[]{0,1,7}[i%3],i%3));PanelCards cards=new PanelCards();String first=payload(p,"maps");check(cards.accept(lines(first)),"Map payload selects card layout");for(int i=0;i<6;i++)rectangle(cards,28+i%2*232,124+i/2*52,220,44,"open "+i);rectangle(cards,260,286,220,22,"page 1");PrototypePanel.handle(p,"arpgproto page 1");cards.accept(lines(payload(p,"maps")));check("open 6".equals(cards.actionAt(30,130))&&"open 7".equals(cards.actionAt(270,130)),"Second page exposes only remaining maps");
  Player crafter=PrototypeIntegrationCheck.player("cardcrafter",70);crafter.allowSaveRequests=false;crafter.setAttribute("tutorial-stage",11);for(int slot=0;slot<8;slot++)crafter.getInventory().set(slot,MapRuns.gem(slot+1,slot%2==1));String landing=payload(crafter,"craft");cards.accept(lines(landing));for(int i=0;i<6;i++)rectangle(cards,28+i%2*232,96+i/2*52,220,44,"select "+i);check("page 1".equals(cards.actionAt(270,290)),"Gem inventory paginates");
  Item active=MapRuns.gem(2,false,4);crafter.getInventory().set(10,active);crafter.setAttribute("craft-slot",10);crafter.setAttribute("craft-uuid",active.getRoll().getInstanceId());String selected=payload(crafter,"craft");cards.accept(lines(selected));check(Arrays.stream(lines(selected)).noneMatch(line->line.startsWith("learn ")),"Active gems no longer expose abstract Learn choices");check(cards.actionAt(50,140)==null,"Physical socketing instructions are inert");
  Item support=MapRuns.gem(2,true,1);crafter.getInventory().set(10,support);crafter.setAttribute("craft-uuid",support.getRoll().getInstanceId());selected=payload(crafter,"craft");cards.accept(lines(selected));check(Arrays.stream(lines(selected)).noneMatch(line->line.startsWith("learn ")),"Support gems no longer expose passive-library choices");check(cards.actionAt(50,140)==null,"Support instructions defer to the K loadout");
  check(!cards.accept(new String[]{"guide","home\tBase"})&&cards.actionAt(30,130)==null,"Non-card categories clear old targets");System.out.println("Passed "+checks+" physical-gem card layout and click-boundary checks.");
 }
}
